const IDX = { fr: 0, en: 1, ar: 2 };
function t(key, params = {}, fallback) {
  const e = D[key];
  let s = e ? (e[IDX[S.lang]] ?? e[0]) : (fallback ?? key);
  return String(s).replace(/\{(\w+)\}/g, (_, k) => (params[k] ?? ''));
}
